def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    seeds = [(y, x) for y in range(H) for x in range(W) if g[y, x] not in (0, 5)]
    owner = {}
    from collections import deque
    q = deque()
    for s in seeds:
        owner[s] = g[s]
        q.append(s)
    while q:
        y, x = q.popleft()
        for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny, nx = y+dy, x+dx
            if 0 <= ny < H and 0 <= nx < W and g[ny, nx] == 0 and (ny, nx) not in owner:
                owner[(ny, nx)] = owner[(y, x)]
                q.append((ny, nx))
    out = g.copy()
    for s in seeds:
        c = g[s]
        for (y, x), col in owner.items():
            if col == c and g[y, x] == 0:
                out[y, x] = c
        emit(out.copy(), f"Flood-filled the black pocket around the colour-{c} seed at {s} through 4-connected 0 cells, stopping at grey walls.")
    emit(out.copy(), "All seed pockets filled; final grid.")
    return out
